# Run by CRuby (tools/make_root.sh): print koruby's RbConfig::MAKEFILE_CONFIG — CRuby's
# (the compiler, flags and $(...) references mkmf builds Makefiles from), with
# koruby's own layout and the compatibility layer's conventions on top.  koruby's
# prelude autoloads the printed file the first time MAKEFILE_CONFIG is named.
puts <<~HEAD
  # RbConfig::MAKEFILE_CONFIG for koruby, generated by tools/make_root.sh from
  # #{RUBY_DESCRIPTION}.  Extensions built with it are CRuby extensions rebuilt for
  # koruby's compatibility layer: foo.kompat.so against cext/include, not linked to a libruby.
  module RbConfig
    MAKEFILE_CONFIG = #{RbConfig::MAKEFILE_CONFIG.inspect}
HEAD
puts <<~'BODY'
    # koruby's layout: every path koruby's own CONFIG has (prefix, *dir, *hdrdir ...)
    CONFIG.each do |k, v|
      MAKEFILE_CONFIG[k] = v.dup if MAKEFILE_CONFIG.key?(k) && v.is_a?(String) && v.start_with?("/")
    end
    %w[ruby_version ruby_install_name RUBY_INSTALL_NAME RUBY_SO_NAME].each { |k| MAKEFILE_CONFIG[k] = CONFIG[k].dup }
    MAKEFILE_CONFIG["DLEXT"] = "kompat.so"             # foo.so is CRuby's, foo.ko.so koruby's native API
    # -lkoruby is root/lib/libkoruby.so: link-time stand-ins for the rb_* the koruby
    # binary exports (make_root.sh); at run time the binary's own definitions win
    MAKEFILE_CONFIG["LIBRUBYARG"] = MAKEFILE_CONFIG["LIBRUBYARG_SHARED"]
    MAKEFILE_CONFIG["LIBRUBYARG_STATIC"] = MAKEFILE_CONFIG["LIBRUBYARG_SHARED"]

    # CRuby's rbconfig.rb helpers (mkmf uses both)
    def self.expand(val, config = CONFIG)
      newval = val.gsub(/\$\$|\$\(([^()]+)\)|\$\{([^{}]+)\}/) {
        var = $&
        if !(v = $1 || $2)
          '$'
        elsif key = config[v = v[/\A[^:]+(?=(?::(.*?)=(.*))?\z)/]]
          pat, sub = $1, $2
          config[v] = false
          config[v] = expand(key, config)
          key = key.gsub(/#{Regexp.quote(pat)}(?=\s|\z)/n) {sub} if pat
          key
        else
          var
        end
      }
      val.replace(newval) unless newval == val
      val
    end

    def self.fire_update!(key, val, mkconf = MAKEFILE_CONFIG, conf = CONFIG)
      return if mkconf[key] == val
      mkconf[key] = val
      keys = [key]
      deps = []
      begin
        re = Regexp.new("\\$\\((?:%1$s)\\)|\\$\\{(?:%1$s)\\}" % keys.join('|'))
        deps |= keys
        keys.clear
        mkconf.each {|k,v| keys << k if re =~ v}
      end until keys.empty?
      deps.each {|k| conf[k] = mkconf[k].dup}
      deps.each {|k| expand(conf[k])}
      deps
    end

    # CRuby's CONFIG is MAKEFILE_CONFIG expanded: add the build keys koruby's table lacks
    __exp = MAKEFILE_CONFIG.transform_values(&:dup)
    __exp.each_value { |v| expand(v, __exp) }
    __exp.each { |k, v| CONFIG[k] = v unless CONFIG.key?(k) }
  end
BODY
